(function(){'use strict';
/* JAH The Electrochemistry generator — jahdb-electrochemistry-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ELCH-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "Oxidation and Reduction Basics", "desc": "Oxidation is loss of electrons, reduction is gain - OIL RIG, the mnemonic every chemistry student learns. The two always occur together in a redox reaction: the reducing agent donates electrons and is itself oxidized, while the oxidizing agent accepts them. Oxidation numbers track the bookkeeping, rising with oxidation and falling with reduction.\nHalf-reactions split the process into oxidation and reduction parts, balanced separately for atoms and charge before recombining. This splitting is more than pedagogy: it is the literal architecture of every electrochemical cell, where the two half-reactions run in separate compartments connected by a wire and a salt bridge. Corrosion, batteries, and electroplating are all redox reactions harnessed or fought.", "how": "Chemists assign oxidation numbers by rule (free elements zero, oxygen usually -2, hydrogen usually +1), identify what is oxidized and reduced, then balance each half-reaction: atoms first with H2O, H+, and e-, then combine so electrons cancel. In cell design the oxidation half-reaction goes at the anode, reduction at the cathode - AN OX, RED CAT. Standard potentials predict spontaneity: positive cell potential means the redox reaction runs on its own, which is the entire basis of galvanic cells.", "keys": ["Oxidation loses electrons; reduction gains them - always paired.", "Oxidation numbers rise with oxidation, fall with reduction.", "Half-reactions are balanced separately, then combined with electrons canceling.", "Anode hosts oxidation, cathode hosts reduction (AN OX, RED CAT).", "Positive cell potential means a spontaneous redox reaction."], "reqs": ["Balanced half-reactions for the redox couple.", "Standard reduction potentials for spontaneity checks.", "Acidic or basic medium specified for balancing."], "stds": ["Half-reaction notation per IUPAC conventions.", "Potentials reported vs SHE in volts."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Bockris JO, Reddy AKN. Modern Electrochemistry. 2nd ed. Plenum; 1998."], "demo": "#!/usr/bin/env python3\n\"\"\"Redox bookkeeping: oxidation numbers in a reaction.\"\"\"\n# Zn + Cu2+ -> Zn2+ + Cu : assign oxidation numbers\nspecies = {\"Zn(s)\": 0, \"Cu2+(aq)\": +2, \"Zn2+(aq)\": +2, \"Cu(s)\": 0}\nfor s, n in species.items():\n    print(f\"  {s:10s} oxidation number {n:+d}\")\nprint(\"Zn: 0 -> +2 oxidized (anode). Cu: +2 -> 0 reduced (cathode).\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Electrochemical Cell", "desc": "An electrochemical cell converts between chemical and electrical energy through redox half-reactions at two electrodes. In a galvanic (voltaic) cell the reaction is spontaneous and produces current - the Daniell cell, zinc in zinc sulfate and copper in copper sulfate joined by a salt bridge, is the classic. In an electrolytic cell an external power supply drives a non-spontaneous reaction, as in electroplating or water splitting.\nCell notation writes the cell as anode | anode solution || cathode solution | cathode, with phase boundaries as single bars and the salt bridge as a double bar. The salt bridge (or membrane) completes the ionic circuit and keeps each compartment electrically neutral. Cell potential, the difference of the two electrode potentials, measures the driving force in volts.", "how": "Builders pick electrode materials and electrolytes from the electrochemical series, arrange oxidation at the anode and reduction at the cathode, and provide ionic conduction between compartments. The measured open-circuit voltage should match E_cathode - E_anode from tables; shortfalls reveal junction potentials, concentration polarization, or side reactions. Current flows from anode to cathode through the external wire (electrons) while ions migrate internally - the complete circuit. Rechargeable cells simply run the same hardware in reverse.", "keys": ["Galvanic cells produce current spontaneously; electrolytic cells consume it.", "Cell notation: anode | anolyte || catholyte | cathode.", "Salt bridge completes the ionic circuit and preserves neutrality.", "Cell potential = E_cathode - E_anode, the driving force in volts.", "Electrons flow anode to cathode externally; ions migrate internally."], "reqs": ["Two redox half-reactions with known potentials.", "Ionic conduction path between compartments.", "Electrode materials stable in the electrolytes."], "stds": ["Cell notation per IUPAC recommendations.", "EMF measurement with high-impedance voltmeter (no current draw)."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Hamann CH, Hamnett A, Vielstich W. Electrochemistry. 2nd ed. Wiley-VCH; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Daniell cell EMF from standard potentials.\"\"\"\nE_cathode = +0.34  # Cu2+/Cu\nE_anode = -0.76    # Zn2+/Zn\nE_cell = E_cathode - E_anode\ndG = -2 * 96485 * E_cell / 1000.0  # kJ/mol, n=2\nprint(f\"E_cell = {E_cell:.2f} V\")\nprint(f\"dG = {dG:.1f} kJ/mol (spontaneous)\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Standard Electrode Potentials", "desc": "Standard electrode potentials rank redox couples by their tendency to gain electrons, measured against the standard hydrogen electrode (SHE) defined as zero. Tables list reduction potentials: strongly positive for noble couples like Au3+/Au, strongly negative for reactive ones like Li+/Li. The more positive the potential, the stronger the oxidizing agent.\nThese potentials predict reaction spontaneity, cell voltages, and corrosion tendencies. A metal with a more negative potential than another will corrode preferentially when coupled - the principle behind sacrificial anodes. Tabulated values assume standard conditions (unit activities, 25 C); the Nernst equation corrects for real concentrations. Sign conventions matter: reduction potentials are standard, and oxidation potentials are their negatives.", "how": "Engineers look up both half-reaction potentials, compute E_cell = E_cathode - E_anode, and read spontaneity from the sign. For corrosion, the galvanic series (the practical, seawater version of the table) predicts which metal of a couple corrodes. Battery designers stack couples to reach target voltages - lead-acid at ~2 V per cell, lithium-ion at ~3.7 V. The tables also flag impossible syntheses: a proposed reaction with negative E_cell needs external energy.", "keys": ["Potentials are measured vs SHE (defined as 0.00 V).", "More positive means stronger oxidizing agent.", "E_cell = E_cathode - E_anode; positive means spontaneous.", "Sacrificial anodes work by being more negative than the protected metal.", "Tables assume standard conditions - Nernst corrects for real ones."], "reqs": ["Standard reduction potentials for both couples.", "Consistent sign convention (reduction potentials).", "Standard-state assumption or Nernst correction."], "stds": ["Potentials in volts vs SHE per IUPAC.", "Electrochemical series data per standard reference tables."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Lide DR, ed. CRC Handbook of Chemistry and Physics. 104th ed. CRC Press; 2023."], "demo": "#!/usr/bin/env python3\n\"\"\"Galvanic series check: which metal corrodes?\"\"\"\nE = {\"zinc\": -0.76, \"iron\": -0.44, \"copper\": +0.34, \"silver\": +0.80}\npairs = [(\"iron\", \"zinc\"), (\"iron\", \"copper\"), (\"copper\", \"silver\")]\nfor a, b in pairs:\n    anode = a if E[a] < E[b] else b\n    print(f\"  {a} + {b}: {anode} corrodes (anode, E={E[anode]:+.2f} V)\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Nernst Equation", "desc": "The Nernst equation corrects electrode potentials for non-standard concentrations: E = E0 - (RT/nF)*ln(Q), or at 25 C, E = E0 - (0.0592/n)*log10(Q). It is the single most-used equation in electrochemistry, linking thermodynamics (through Q, the reaction quotient) to the measurable voltage.\nThe equation explains concentration cells - identical electrodes developing voltage from concentration difference alone - and underlies every potentiometric sensor: pH electrodes, ion-selective electrodes, and oxygen sensors all read concentration through Nernstian slopes of about 59 mV per decade for a one-electron process at room temperature. Deviations from 59 mV/decade diagnose non-ideal behavior, mixed potentials, or electrode fouling.", "how": "Analysts write the reaction quotient Q from the balanced half-reaction, plug in activities (concentrations for dilute solutions), and compute the working potential. Battery engineers use it to predict how cell voltage sags with state of charge. Sensor designers calibrate electrodes against standards and check the slope: Nernstian slope means the sensor is healthy. The equation also sets the theoretical limit of electrowinning and electrorefining voltages.", "keys": ["E = E0 - (RT/nF) ln Q - concentration corrects the potential.", "At 25 C: 59.2/n mV per decade of concentration.", "Concentration cells make voltage from concentration difference alone.", "pH and ion-selective electrodes are Nernstian sensors.", "Non-Nernstian slopes diagnose fouling or mixed potentials."], "reqs": ["Standard potential E0 and electron count n.", "Activities (or concentrations) of all species in Q.", "Temperature for the RT/nF factor."], "stds": ["Nernstian slope verification per sensor calibration standards.", "Activity corrections via Debye-Huckel for non-dilute solutions."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Hamann CH, Hamnett A, Vielstich W. Electrochemistry. 2nd ed. Wiley-VCH; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Nernst: hydrogen electrode potential vs pH at 25 C.\"\"\"\nE0 = 0.0\nprint(\"  pH    E (V vs SHE)\")\nfor ph in range(0, 15, 2):\n    E = E0 - 0.0592 * ph  # n=1, Q = 1/[H+]\n    print(f\"  {ph:3d}    {E:+.3f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Faraday's Laws of Electrolysis", "desc": "Faraday's laws quantify electrolysis: the mass of substance deposited or dissolved is proportional to the charge passed, m = Q*M/(n*F), where F = 96485 C/mol is Faraday's constant. One mole of electrons carries one faraday of charge, depositing M/n grams of a metal of molar mass M and valence n.\nCurrent efficiency compares actual yield to the Faraday prediction; side reactions like hydrogen evolution steal current and lower it. The laws size rectifiers for plating shops, predict battery capacity (ampere-hours from active mass), and calibrate coulometers. They hold regardless of mechanism - charge counting is chemistry-blind, which is exactly why it is so powerful.", "how": "Platers compute plating time from target thickness: mass from area times thickness times density, charge from Faraday's law, time from charge over current, then divide by current efficiency from experience. Battery engineers convert active-material mass to theoretical capacity in Ah. Electrowinning plants size busbars and rectifiers from total current = production rate times nF/M. Deviations from Faraday's law always mean a side reaction worth identifying.", "keys": ["m = Q*M/(n*F): mass scales with charge passed.", "F = 96485 C/mol links moles of electrons to coulombs.", "Current efficiency = actual / theoretical yield.", "Sizes rectifiers, plating times, and battery capacities.", "Deviations always signal a side reaction."], "reqs": ["Target mass or thickness and deposit density.", "Valence n of the electrode reaction.", "Current efficiency estimate for the process."], "stds": ["Charge in coulombs; capacity in ampere-hours.", "Plating thickness per ASTM B659."], "cites": ["Bockris JO, Reddy AKN. Modern Electrochemistry. 2nd ed. Plenum; 1998.", "Schlesinger M, Paunovic M. Modern Electroplating. 5th ed. Wiley; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Faraday law: copper plating time for a target thickness.\"\"\"\nimport math\nM, n, F = 63.55, 2, 96485.0  # g/mol, valence, C/mol\nrho_cu = 8.96  # g/cm3\narea_cm2, thick_um, I, eff = 100.0, 25.0, 5.0, 0.95\nmass = area_cm2 * thick_um * 1e-4 * rho_cu\nQ = mass / M * n * F / eff\nprint(f\"Mass to deposit: {mass:.2f} g\")\nprint(f\"Plating time at {I} A: {Q/I/60:.1f} min\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Galvanic vs Electrolytic Cells", "desc": "The galvanic/electrolytic distinction is about spontaneity, not hardware: the same electrodes can form either, depending on whether the reaction drives current or current drives the reaction. Galvanic cells (batteries, fuel cells, corrosion cells) run downhill in free energy and deliver power; electrolytic cells (plating baths, electrolyzers, electrorefiners) are pushed uphill by an external supply.\nSign conventions flip between the two, which is the classic confusion: the anode is always where oxidation happens, but it is negative in galvanic cells and positive in electrolytic ones. Keeping 'anode = oxidation' fixed and letting the sign follow avoids the trap. Rechargeable batteries alternate between modes every cycle - galvanic on discharge, electrolytic on charge.", "how": "Designers first ask which direction energy flows, then assign terminals: in galvanic mode the negative terminal is the anode; in electrolytic mode the positive terminal is the anode. Chargers are sized to overcome the cell voltage plus overpotentials - the extra voltage kinetics demands. Corrosion engineers recognize corrosion cells as tiny galvanic cells and fight them by breaking the circuit (coatings), removing the electrolyte path, or reversing the polarity (cathodic protection).", "keys": ["Same hardware can be galvanic or electrolytic - direction of energy flow decides.", "Anode is always oxidation; its sign flips between modes.", "Galvanic delivers power; electrolytic consumes it.", "Charging voltage must exceed cell voltage plus overpotentials.", "Corrosion cells are galvanic cells - fight them as circuits."], "reqs": ["Reaction spontaneity (sign of E_cell or delta G).", "External circuit: load vs power supply.", "Overpotential estimates for the electrolytic direction."], "stds": ["Cell polarity notation per IUPAC.", "Charger voltage windows per battery standards (e.g., IEEE 1188)."], "cites": ["Hamann CH, Hamnett A, Vielstich W. Electrochemistry. 2nd ed. Wiley-VCH; 2007.", "Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"Cell mode from E_cell sign.\"\"\"\ncases = [(\"Daniell\", 1.10), (\"Water splitting\", -1.23), (\"Lead-acid discharging\", 2.05)]\nfor name, E in cases:\n    mode = \"GALVANIC (delivers power)\" if E > 0 else \"ELECTROLYTIC (needs power)\"\n    print(f\"  {name:22s} E={E:+.2f} V -> {mode}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Conductivity and Electrolytes", "desc": "Electrolytes conduct by ion migration, not electrons: cations drift toward the cathode, anions toward the anode, each carrying a share of current given by its transport number. Conductivity kappa (S/cm) rises with concentration at first, then falls as ion pairing and viscosity take over - the Kohlrausch square-root law describes dilute strong electrolytes.\nMolar conductivity at infinite dilution is the sum of independent ionic contributions (Kohlrausch's law of independent migration), which is how tables are built from single-ion values. Weak electrolytes dissociate partially, and conductivity reveals the degree of dissociation. Cell resistance - the iR drop - is set by geometry over conductivity, and minimizing it is central to battery, fuel cell, and electrolyzer design.", "how": "Formulators pick salts for high solubility, high mobility (small, highly charged ions move well but hydrate heavily), and stability at the electrodes. Conductivity meters with calibrated cell constants monitor water purity, plating baths, and process streams. Designers compute iR drop as I*l/(kappa*A) and shrink it with thin separators, high-kappa electrolytes, and large areas - the reason high-power cells use thin, large-area electrodes. Supporting electrolyte swamps migration in analytical work so diffusion controls.", "keys": ["Conduction by ion migration; transport numbers split the current.", "Conductivity rises then falls with concentration.", "Kohlrausch: molar conductivity sums independent ionic contributions.", "iR drop = I*l/(kappa*A) - shrink with thin, large-area, high-kappa designs.", "Conductivity monitoring tracks bath health and water purity."], "reqs": ["Salt identity, concentration, temperature.", "Cell constant for the conductivity probe.", "Geometry for iR-drop calculation."], "stds": ["Conductivity in S/cm; cell constants per ASTM D1125.", "Ultrapure water spec 18.2 Mohm-cm at 25 C."], "cites": ["Bockris JO, Reddy AKN. Modern Electrochemistry. 2nd ed. Plenum; 1998.", "Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"iR drop in an electrochemical cell.\"\"\"\nkappa = 0.05  # S/cm, typical aqueous electrolyte\nl_cm, A_cm2 = 2.0, 50.0\nR = l_cm / (kappa * A_cm2)\nprint(f\"Cell resistance: {R:.3f} ohm\")\nfor I in (1, 10, 50):\n    print(f\"  I={I:3d} A -> iR drop {I*R:.2f} V\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Electrochemical Series", "desc": "The electrochemical series orders elements by standard electrode potential into a single ladder from lithium at the bottom to fluorine at the top. Position predicts displacement reactions: any metal reduces the ions of metals above it in the series, which is why zinc displaces copper from solution but copper cannot displace zinc.\nThe series is the quick-look version of the potential tables, extended in practice by the galvanic series for real environments like seawater, where oxide films and passivity shuffle the order. Reactivity trends, corrosion pairs, and battery couple choices all read off this ladder. Its limits matter too: kinetics can override thermodynamics, and concentrated or complexing media shift effective potentials.", "how": "Teachers and engineers use the series to predict single-displacement reactions and rank reducing strength at a glance. Corrosion engineers consult the galvanic series variant for the actual environment - stainless steel behaves nobly in seawater only while its passive film holds. Battery chemists scan the series for high-voltage couples with practical kinetics: lithium at the bottom and transition-metal oxides at the top is no accident. Any prediction gets checked against kinetic reality before hardware is built.", "keys": ["One ladder from Li (most reducing) to F2 (most oxidizing).", "Lower metals displace ions of higher metals.", "The galvanic series is the practical seawater variant.", "Passivity and films can shuffle real-world order.", "Thermodynamics predicts; kinetics disposes."], "reqs": ["Standard potentials or a published series table.", "Environment-specific series (e.g., seawater) for corrosion work.", "Kinetic check before committing to hardware."], "stds": ["Series data per standard electrochemical tables.", "Galvanic series per ASTM G82 guidance."], "cites": ["Lide DR, ed. CRC Handbook of Chemistry and Physics. 104th ed. CRC Press; 2023.", "Revie RW, Uhlig HH. Corrosion and Corrosion Control. 4th ed. Wiley; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Displacement prediction from the series.\"\"\"\nE = {\"Li\": -3.04, \"Zn\": -0.76, \"Fe\": -0.44, \"Cu\": +0.34, \"Ag\": +0.80, \"Au\": +1.50}\nranked = sorted(E.items(), key=lambda kv: kv[1])\nprint(\"Series (reducing strength decreasing):\")\nprint(\"  \" + \" > \".join(f\"{m}({v:+.2f})\" for m, v in ranked))\nprint(\"Zn displaces Cu2+:\", E[\"Zn\"] < E[\"Cu\"])\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "pH and Electrochemical Measurement", "desc": "The glass pH electrode is electrochemistry's most familiar sensor: a thin glass membrane develops a potential proportional to pH with a near-Nernstian slope of about -59 mV/pH at 25 C. Paired with a reference electrode (usually Ag/AgCl), it reads hydrogen-ion activity across 0-14 with simple two-point calibration.\nGood measurement demands care: electrodes drift, dry out, and foul; buffers bracket the expected range; temperature compensation corrects the slope. Ion-selective electrodes extend the principle to sodium, potassium, calcium, fluoride, and more, each with its membrane chemistry and interferences. Potentiometry - measuring voltage at zero current - is the common thread, and its simplicity keeps it everywhere from labs to process lines to aquariums.", "how": "Technicians calibrate with two buffers bracketing the sample, rinse between, and measure with gentle stirring to a stable reading. Slope checks (95-102% of theoretical) flag aging electrodes; cleaning protocols revive fouled ones. For process control, retractable probes with automatic cleaning hold calibration for weeks. The same potentiometric principle with different membranes measures the ions that matter in blood gas analyzers, water plants, and food production.", "keys": ["Glass electrode slope ~ -59 mV/pH at 25 C (Nernstian).", "Two-buffer calibration bracketing the sample.", "Reference electrode (Ag/AgCl) completes the cell.", "Slope check 95-102% flags electrode health.", "Ion-selective electrodes extend the method to Na+, K+, Ca2+, F-, and more."], "reqs": ["Calibrated buffers bracketing the measurement range.", "Temperature compensation or control.", "Clean, hydrated electrode with verified slope."], "stds": ["pH measurement per ASTM E70.", "Buffer traceability to NIST standards."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"pH from electrode voltage (calibrated).\"\"\"\nE7, slope = 0.000, -0.0592  # V at pH 7, V/pH\nfor E_meas in (0.118, 0.030, -0.150):\n    ph = 7 + (E_meas - E7) / slope\n    print(f\"  E={E_meas:+.3f} V -> pH {ph:.2f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Reference Electrodes", "desc": "Reference electrodes provide the stable, known potential against which working electrodes are measured - the anchor of all potentiometry. The standard hydrogen electrode is the thermodynamic reference but impractical daily; the silver/silver-chloride (Ag/AgCl) and saturated calomel (SCE) electrodes are the workhorses, with potentials fixed by sparingly soluble salts.\nA good reference is non-polarizable (its potential barely shifts with tiny currents), stable over time and temperature, and reproducible. The liquid junction - where reference filling solution meets sample - adds a small junction potential, minimized with equitransferent salts like KCl. Modern double-junction designs protect samples from chloride contamination, and solid-state references serve harsh process environments.", "how": "Electrochemists pick Ag/AgCl for general work (3 M KCl filling, +0.210 V vs SHE at 25 C) and convert all reported potentials to a common scale. They store references in filling solution, never dry, and replace filling solution on schedule; a drifting reference poisons every measurement made against it. In non-aqueous work, quasi-references (silver wire) are calibrated in situ with ferrocene as an internal standard. Three-electrode cells keep reference current near zero so its potential stays put.", "keys": ["Reference electrodes anchor every potential measurement.", "SHE is the thermodynamic zero; Ag/AgCl and SCE are the practical ones.", "Good references are non-polarizable, stable, reproducible.", "Liquid-junction potentials are minimized with KCl bridges.", "Store wet, refill on schedule - a drifting reference ruins data."], "reqs": ["Reference type and filling solution documented.", "Potential converted to a common scale (usually SHE).", "Storage and maintenance schedule."], "stds": ["Reference potentials per IUPAC; Ag/AgCl (3M KCl) +0.210 V vs SHE at 25 C.", "Junction design per standard electrochemical practice."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Inzelt G, Lewenstam A, Scholz F, eds. Handbook of Reference Electrodes. Springer; 2013."], "demo": "#!/usr/bin/env python3\n\"\"\"Convert measured potentials to the SHE scale.\"\"\"\nrefs = {\"Ag/AgCl (3M KCl)\": 0.210, \"SCE\": 0.244}\nE_vs_agcl = 0.350  # measured\nE_she = E_vs_agcl + refs[\"Ag/AgCl (3M KCl)\"]\nprint(f\"Measured: {E_vs_agcl:.3f} V vs Ag/AgCl\")\nprint(f\"  = {E_she:.3f} V vs SHE\")\nfor name, Eref in refs.items():\n    print(f\"  = {E_she - Eref:+.3f} V vs {name}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Double Layer and Capacitance", "desc": "Where electrode meets electrolyte, charge separates into the electrical double layer: electrons (or holes) on the metal side, counter-ions lined up on the solution side. Helmholtz pictured a rigid sheet; Gouy and Chapman added a diffuse cloud; Stern combined both. The result behaves like a capacitor of roughly 10-40 microfarads per cm2.\nCharging this capacitor draws non-faradaic (capacitive) current that carries no chemistry - the background every voltammetry experiment must subtract. The potential of zero charge, where the metal carries no excess charge, is a fundamental surface parameter. Supercapacitors deliberately maximize double-layer area with porous carbons, storing energy electrostatically for fast charge/discharge.", "how": "Electroanalysts measure double-layer capacitance from the scan-rate dependence of background current (i = C*nu) and subtract it to reveal faradaic peaks. The capacitance also reports surface area and adsorption - a rising capacitance signals a contaminant film. Supercapacitor engineers maximize accessible surface area (thousands of m2/g in activated carbon) while keeping pores wide enough for ions to enter. Impedance spectroscopy separates double-layer capacitance from charge-transfer resistance by frequency.", "keys": ["Charge separation at the interface acts as a ~10-40 uF/cm2 capacitor.", "Helmholtz + Gouy-Chapman + Stern models describe it.", "Capacitive current is background - subtract it in voltammetry.", "Potential of zero charge is a key surface parameter.", "Supercapacitors maximize double-layer area for fast storage."], "reqs": ["Electrode area (true vs geometric).", "Electrolyte composition and concentration.", "Potential window free of faradaic reactions for capacitance measurement."], "stds": ["Capacitance in F/cm2 of true area.", "Supercapacitor testing per IEC 62391."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Conway BE. Electrochemical Supercapacitors. Kluwer; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Capacitive background current vs scan rate.\"\"\"\nCdl_uF = 20.0  # uF/cm2\nA = 1.0  # cm2\nprint(\" scan rate (mV/s)   capacitive current (uA)\")\nfor nu in (10, 50, 100, 500):\n    i = Cdl_uF * A * nu / 1000.0\n    print(f\"  {nu:6d}              {i:7.2f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Overpotential Basics", "desc": "Overpotential is the extra voltage beyond the thermodynamic value needed to drive an electrode reaction at a useful rate - the price of kinetics. It splits into activation overpotential (getting over the reaction barrier), concentration overpotential (reactants depleted at the surface), and ohmic drop (iR in the cell).\nGood electrocatalysts slash activation overpotential: platinum needs only millivolts for hydrogen evolution where lead needs nearly a volt. Tafel plots (overpotential vs log current) reveal the mechanism through their slopes. Minimizing overpotential is the economic core of electrolyzers, batteries, and fuel cells - every wasted millivolt is lost energy and heat.", "how": "Engineers measure polarization curves (voltage vs current) and decompose the losses: iR from current-interrupt or impedance, activation from Tafel slopes, concentration from limiting currents. They attack each: better catalysts and higher temperature for activation, stirring and flow for concentration, thin cells and conductive electrolytes for iR. Battery fast-charging limits are set by overpotentials that would plate lithium or evolve gas. Reporting overpotential at a benchmark current density (e.g., 10 mA/cm2) standardizes catalyst comparisons.", "keys": ["Overpotential = extra voltage kinetics demands beyond thermodynamics.", "Three parts: activation, concentration, ohmic (iR).", "Catalysts cut activation overpotential dramatically.", "Tafel slopes reveal reaction mechanism.", "Every millivolt wasted is lost energy - minimizing it is the economic core."], "reqs": ["Thermodynamic (equilibrium) potential as baseline.", "Current density for the comparison point.", "Separation of iR from kinetic losses."], "stds": ["Overpotential reported at benchmark current densities (e.g., 10 mA/cm2).", "iR compensation per standard electrochemical practice."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Hamann CH, Hamnett A, Vielstich W. Electrochemistry. 2nd ed. Wiley-VCH; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Cell voltage with overpotentials: electrolyzer vs ideal.\"\"\"\nE_rev = 1.23  # water splitting, V\neta_act, eta_conc, iR = 0.35, 0.05, 0.12\nV_cell = E_rev + eta_act + eta_conc + iR\neff = E_rev / V_cell\nprint(f\"V_cell = {V_cell:.2f} V  (ideal {E_rev} V)\")\nprint(f\"Voltage efficiency: {eff*100:.1f}%\")\n"}, {"tier": "Compounded", "g": "Kinetics & Methods", "title": "Butler-Volmer Kinetics", "desc": "The Butler-Volmer equation is the central kinetic law of electrochemistry, relating current density to overpotential: i = i0*[exp(alpha_a*nF*eta/RT) - exp(-alpha_c*nF*eta/RT)]. The exchange current density i0 measures intrinsic catalytic activity - large i0 means a fast, reversible couple needing little overpotential; tiny i0 means a sluggish reaction.\nAt large overpotentials one exponential dominates and the equation reduces to Tafel form, eta = a + b*log(i), with the Tafel slope diagnosing mechanism. Platinum's i0 for hydrogen evolution is orders of magnitude above lead's, which is why lead-acid batteries can hold charge without gassing. The transfer coefficients alpha capture the symmetry of the energy barrier, typically near 0.5.", "how": "Kineticists fit polarization data to Butler-Volmer to extract i0 and alpha, comparing catalysts on equal footing. Tafel plots linearize the high-overpotential region; slopes near 120 mV/decade suggest a one-electron rate-determining step, 60 or 40 mV/decade suggest more complex paths. Battery and fuel-cell models embed Butler-Volmer at each electrode to predict voltage under load. Corrosion rates come from the same equation at the corrosion potential, where anodic and cathodic currents balance - the basis of Tafel extrapolation.", "keys": ["i = i0*(exp(anodic) - exp(cathodic)) - current from overpotential.", "Exchange current density i0 measures intrinsic speed.", "Large overpotential gives Tafel form: eta = a + b log i.", "Tafel slopes diagnose the reaction mechanism.", "Corrosion current comes from Butler-Volmer at the corrosion potential."], "reqs": ["Equilibrium potential and overpotential range.", "Temperature for the RT/F factors.", "iR-corrected data for clean kinetic fits."], "stds": ["Kinetic parameters reported with temperature and electrolyte.", "Tafel analysis per standard electrochemical practice."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Hamann CH, Hamnett A, Vielstich W. Electrochemistry. 2nd ed. Wiley-VCH; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Butler-Volmer polarization curve.\"\"\"\nimport math\ni0, n, T = 1e-3, 1, 298.0  # A/cm2\nF_RT = 96485 / (8.314 * T)\nprint(\"  eta (mV)   i (mA/cm2)\")\nfor eta_mv in (-200, -100, -50, 50, 100, 200):\n    eta = eta_mv / 1000\n    i = i0 * (math.exp(0.5*n*F_RT*eta) - math.exp(-0.5*n*F_RT*eta))\n    print(f\"  {eta_mv:+5d}     {i*1000:+9.3f}\")\n"}, {"tier": "Compounded", "g": "Kinetics & Methods", "title": "Mass Transport: Diffusion, Migration, Convection", "desc": "Reactants reach electrodes by three transport modes: diffusion down concentration gradients, migration of ions in the electric field, and convection by fluid motion. The Nernst-Planck equation combines all three into the flux of each species. In analytical work, excess supporting electrolyte suppresses migration so diffusion controls - the clean, calculable case.\nDiffusion-limited current is the workhorse measurement: i_d = nFADC/delta, proportional to bulk concentration, which makes amperometric sensors quantitative. The diffusion layer thickness delta shrinks with stirring or electrode rotation - the rotating disk electrode gives the exact Levich equation. Cottrell's equation describes current decay after a potential step as the layer grows with sqrt(t).", "how": "Analysts add 0.1 M supporting electrolyte to kill migration, then use diffusion-limited currents for concentration measurement. Rotating-disk voltammetry varies rotation rate to separate kinetic from transport limits via Koutecky-Levich plots. Sensor designers shrink diffusion distances with microelectrodes, reaching steady state in milliseconds. Battery engineers enhance convection with flow fields to sustain high currents without concentration polarization.", "keys": ["Three modes: diffusion, migration, convection (Nernst-Planck).", "Supporting electrolyte suppresses migration for clean analysis.", "Diffusion-limited current is proportional to concentration.", "Rotating disk gives exact transport via the Levich equation.", "Microelectrodes reach steady state fast by shrinking distances."], "reqs": ["Diffusion coefficients of the electroactive species.", "Supporting electrolyte concentration (>> analyte).", "Hydrodynamic conditions: stagnant, stirred, or rotating."], "stds": ["Diffusion coefficients in cm2/s with temperature stated.", "RDE measurements per standard Levich/Koutecky-Levich analysis."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Pleskov YV, Filinovskii VY. The Rotating Disc Electrode. Consultants Bureau; 1976."], "demo": "#!/usr/bin/env python3\n\"\"\"Levich: limiting current vs rotation rate (RDE).\"\"\"\nimport math\nn, F, A, D, nu, C = 1, 96485.0, 0.196, 7e-6, 0.01, 1e-6  # cm units, mol/cm3\nprint(\"  rpm     i_levich (uA)\")\nfor rpm in (100, 400, 900, 1600, 2500):\n    w = rpm * 2 * math.pi / 60\n    i = 0.62 * n * F * A * D ** (2/3) * nu ** (-1/6) * w ** 0.5 * C\n    print(f\"  {rpm:4d}    {i*1e6:8.1f}\")\n"}, {"tier": "Compounded", "g": "Kinetics & Methods", "title": "Cyclic Voltammetry", "desc": "Cyclic voltammetry (CV) sweeps the electrode potential linearly back and forth and records current, producing the duck-shaped voltammogram that is electrochemistry's most recognizable fingerprint. Peak positions reveal formal potentials, peak separations diagnose reversibility (59/n mV for reversible at 25 C), and peak currents scale with sqrt(scan rate) for diffusion-controlled couples via Randles-Sevcik.\nCV is the first experiment run on any new redox system: it screens reversibility, counts electrons, spots coupled chemical reactions (missing return peaks), and measures diffusion coefficients. Variations - differential pulse, square wave - trade the full picture for sensitivity, reaching nanomolar detection. From battery electrode screening to biosensors, CV is the entry point.", "how": "Experimentalists pick a potential window avoiding solvent breakdown, run several scan rates, and read the diagnostics: delta_Ep near 59/n mV and i_pa/i_pc near 1 means reversible; wider separation means quasi-reversible kinetics to fit; no return peak means a following chemical reaction (EC mechanism). Randles-Sevcik converts peak current to concentration or diffusion coefficient. Background subtraction and iR compensation clean the data before interpretation.", "keys": ["Triangular potential sweep produces the classic duck-shaped voltammogram.", "59/n mV peak separation marks reversibility at 25 C.", "Peak current scales with sqrt(scan rate) - Randles-Sevcik.", "Missing return peak reveals coupled chemical reactions.", "First experiment for any new redox system."], "reqs": ["Potential window within solvent/electrolyte stability.", "Multiple scan rates for the reversibility diagnosis.", "iR compensation and background subtraction."], "stds": ["Potentials vs a documented reference; scan rates in V/s.", "Reversibility criteria per standard CV diagnostics."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Elgrishi N et al. A practical beginner guide to cyclic voltammetry. J Chem Educ 95:197-206; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Randles-Sevcik: peak current vs scan rate.\"\"\"\nimport math\nn, A, D, C = 1, 0.07, 6.5e-6, 1e-6  # cm2, cm2/s, mol/cm3\nprint(\" scan rate (mV/s)   ip (uA)\")\nfor nu_mv in (10, 25, 50, 100, 250):\n    nu = nu_mv / 1000\n    ip = 2.69e5 * n ** 1.5 * A * D ** 0.5 * C * nu ** 0.5\n    print(f\"  {nu_mv:6d}            {ip*1e6:6.1f}\")\n"}, {"tier": "Compounded", "g": "Kinetics & Methods", "title": "Electrochemical Impedance Spectroscopy", "desc": "Electrochemical Impedance Spectroscopy (EIS) probes the interface with small AC signals across a wide frequency range, separating processes by their time constants: solution resistance at high frequency, charge-transfer resistance and double-layer capacitance mid-range, diffusion (Warburg) at low frequency. Nyquist plots (imaginary vs real impedance) show these as semicircles and tails.\nEquivalent-circuit modeling translates spectra into physical parameters: R_ct for kinetics, C_dl for area, Warburg coefficient for diffusion. EIS is non-destructive and information-rich, used for battery state-of-health, corrosion-rate monitoring, coating evaluation, and fuel-cell diagnostics. The Kramers-Kronig relations check data validity - a failing check means the system drifted during measurement.", "how": "Practitioners verify steady state first, then sweep from kHz to mHz with small perturbation (5-10 mV) to stay linear. They fit equivalent circuits starting from the simplest (Randles circuit) and add elements only as justified, watching for overfitting - different circuits can fit the same spectrum. Battery management systems use single-frequency impedance as a fast health proxy. Corrosion engineers read R_ct inversely as corrosion rate for inhibitor screening.", "keys": ["AC perturbation across frequencies separates processes by time constant.", "Nyquist plots show charge transfer as semicircles, diffusion as Warburg tails.", "Equivalent circuits map spectra to R_ct, C_dl, diffusion parameters.", "Kramers-Kronig checks data validity.", "Non-destructive: batteries, coatings, corrosion, fuel cells."], "reqs": ["Steady-state system during the sweep.", "Small perturbation amplitude for linearity.", "Frequency range spanning all processes of interest."], "stds": ["Impedance in ohm-cm2; EIS validation per ASTM G106.", "Equivalent-circuit fitting with error estimates."], "cites": ["Barsoukov E, Macdonald JR, eds. Impedance Spectroscopy. 3rd ed. Wiley; 2018.", "Orazem ME, Tribollet B. Electrochemical Impedance Spectroscopy. 2nd ed. Wiley; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Randles circuit Nyquist semicircle.\"\"\"\nimport math, cmath\nRs, Rct, Cdl, sigma = 5.0, 100.0, 20e-6, 50.0\nprint(\"   f (Hz)     Z_real     -Z_imag\")\nfor f in (10000, 1000, 100, 10, 1, 0.1):\n    w = 2 * math.pi * f\n    Zw = sigma / math.sqrt(w) * (1 - 1j)\n    Z = Rs + 1 / (1j * w * Cdl + 1 / (Rct + Zw))\n    print(f\"  {f:8.1f}   {Z.real:8.1f}    {-Z.imag:8.1f}\")\n"}, {"tier": "Compounded", "g": "Corrosion", "title": "Corrosion Mechanisms", "desc": "Corrosion is electrochemical dissolution of metals: anodic metal oxidation coupled with cathodic reduction (usually oxygen reduction or hydrogen evolution). Uniform corrosion thins evenly; pitting drills deep local holes through passive films; crevice corrosion attacks shielded spots; galvanic corrosion couples dissimilar metals; stress-corrosion cracking combines tension with a specific environment to fail suddenly.\nThe mixed-potential theory sets the corrosion potential where anodic and cathodic currents balance, and the corrosion current there converts via Faraday's law to penetration rate. Pourbaix diagrams map immunity, corrosion, and passivity regions vs potential and pH. Stainless steels survive by passivity - a nanometer chromium-oxide film - which chloride punctures, hence pitting's danger.", "how": "Engineers identify the mechanism from morphology (pits vs uniform vs cracks), then select countermeasures: material upgrade, coatings, inhibitors, cathodic protection, or design changes (drain crevices, insulate dissimilar metals). Polarization curves quantify corrosion current by Tafel extrapolation. Laboratory salt-spray and electrochemical tests rank materials, but field validation remains essential - real environments surprise. Inspection programs target the known vulnerable geometries: welds, crevices, and waterlines.", "keys": ["Anodic dissolution coupled with cathodic reduction - always a cell.", "Pitting, crevice, galvanic, SCC: distinct morphologies, distinct fixes.", "Corrosion potential is where anodic and cathodic currents balance.", "Pourbaix diagrams map immunity, corrosion, passivity.", "Stainless steels rely on passive films that chloride attacks."], "reqs": ["Environment: electrolyte, pH, temperature, oxidizers.", "Material and microstructure (welds, heat treatment).", "Geometry: crevices, dissimilar-metal contacts, stresses."], "stds": ["Corrosion rates in mm/year per ASTM G102.", "Salt-spray testing per ASTM B117."], "cites": ["Revie RW, Uhlig HH. Corrosion and Corrosion Control. 4th ed. Wiley; 2008.", "Jones DA. Principles and Prevention of Corrosion. 2nd ed. Prentice Hall; 1995."], "demo": "#!/usr/bin/env python3\n\"\"\"Corrosion rate from corrosion current (iron).\"\"\"\ni_corr_uA = 10.0  # uA/cm2\nM, n, rho = 55.85, 2, 7.87  # g/mol, valence, g/cm3\nF = 96485.0\n# penetration rate mm/year\nrate = i_corr_uA * 1e-6 * M / (n * F * rho) * 10 * 365 * 24 * 3600\nprint(f\"i_corr = {i_corr_uA} uA/cm2 -> {rate:.3f} mm/year\")\nprint(\"(1 uA/cm2 ~= 0.0116 mm/y for iron)\")\n"}, {"tier": "Compounded", "g": "Corrosion", "title": "Cathodic Protection", "desc": "Cathodic protection stops corrosion by making the structure the cathode of an electrochemical cell: supply electrons and the metal cannot oxidize. Sacrificial anode systems bolt on zinc, aluminum, or magnesium anodes that corrode instead - simple, no power needed, used on ship hulls and water heaters. Impressed-current systems drive current from rectifiers through inert anodes, protecting pipelines and tank farms over kilometers.\nProtection is verified by potential criteria: steel in soil/aerated water is protected at -850 mV vs Cu/CuSO4 (or 100 mV polarization shift). Overprotection wastes anodes and can damage coatings or embrittle high-strength steels with hydrogen. Design balances current distribution - throwing power - against anode consumption and monitoring with reference electrodes.", "how": "Designers compute current demand from coated vs bare area and environment resistivity, size anodes for the design life via Faraday's law, and place them for uniform distribution. They commission by measuring polarized potentials against the criteria and adjust rectifier output. Monitoring is permanent: test stations along pipelines, periodic hull potential surveys on ships. Stray-current interference from transit systems or neighboring CP systems is investigated when potentials misbehave.", "keys": ["Make the structure the cathode - supply electrons, stop oxidation.", "Sacrificial anodes (Zn, Al, Mg) corrode instead; no power needed.", "Impressed current protects kilometers of pipeline from rectifiers.", "Steel protected at -850 mV vs Cu/CuSO4 (or 100 mV shift).", "Overprotection damages coatings and embrittles high-strength steel."], "reqs": ["Structure area, coating quality, soil/water resistivity.", "Design life for anode sizing.", "Reference electrodes for potential monitoring."], "stds": ["CP criteria per NACE SP0169.", "Anode consumption via Faraday law with efficiency factors."], "cites": ["Revie RW, Uhlig HH. Corrosion and Corrosion Control. 4th ed. Wiley; 2008.", "Peabody AW. Control of Pipeline Corrosion. 2nd ed. NACE; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Sacrificial anode life for a protected structure.\"\"\"\nI_mA, years = 500.0, 20.0  # protection current, design life\ncapacity_Ah_per_kg = 780.0  # zinc\nutilization = 0.85\nmass = I_mA / 1000 * 24 * 365 * years / (capacity_Ah_per_kg * utilization)\nprint(f\"Zinc needed for {years:.0f} years at {I_mA:.0f} mA: {mass:.1f} kg\")\n"}, {"tier": "Compounded", "g": "Industrial Processes", "title": "Electroplating Fundamentals", "desc": "Electroplating deposits metal from solution onto a conductive surface: the workpiece is the cathode, metal ions reduce onto it, and Faraday's law sets the thickness from charge passed. Decorative chrome, corrosion-resistant zinc, and precious-metal finishes are plating products; printed-circuit-board copper is plating at micro-scale.\nBath chemistry controls everything: metal salt concentration, complexing agents (cyanide historically, now alkaline non-cyanide), pH, brighteners, levelers, and temperature. Throwing power - uniform coverage in recesses - depends on polarization and conductivity. Pretreatment (cleaning, etching, activation) decides adhesion more than the plating step itself. Current density must stay below the burning threshold where deposits turn rough and powdery.", "how": "Platers clean and activate parts, rack them for good current distribution (auxiliary anodes and shields for recesses), and run at the vendor's current-density window with agitation. Thickness is timed by Faraday's law divided by cathode efficiency, verified by XRF or coulometric stripping. Bath health is tracked with Hull-cell panels and chemical analysis; brightener dosing follows ampere-hour consumption. Waste treatment - precipitation of metals, destruction of complexers - is part of the process design, not an afterthought.", "keys": ["Workpiece is the cathode; Faraday law sets thickness from charge.", "Bath chemistry (complexers, brighteners, pH) controls deposit quality.", "Pretreatment decides adhesion more than plating does.", "Throwing power governs coverage in recesses.", "Stay below burning current density; verify thickness by XRF."], "reqs": ["Clean, activated conductive surface.", "Bath composition within vendor windows.", "Current density in the bright range with agitation."], "stds": ["Plating thickness per ASTM B659; adhesion per ASTM B571.", "Wastewater metals per EPA effluent guidelines."], "cites": ["Schlesinger M, Paunovic M. Modern Electroplating. 5th ed. Wiley; 2010.", "Durney LJ, ed. Electroplating Engineering Handbook. 4th ed. Van Nostrand; 1984."], "demo": "#!/usr/bin/env python3\n\"\"\"Chrome plating thickness check (Faraday with efficiency).\"\"\"\nM, n, F, rho = 52.0, 6, 96485.0, 7.19  # Cr: g/mol, valence, C/mol, g/cm3\nI_A, t_min, eff = 8.0, 30.0, 0.15  # chrome baths run low efficiency\nmass = I_A * t_min * 60 * eff / (n * F) * M\narea = 200.0  # cm2\nthick_um = mass / rho / area * 1e4\nprint(f\"Deposit: {mass:.2f} g -> {thick_um:.1f} um on {area:.0f} cm2\")\n"}, {"tier": "Compounded", "g": "Industrial Processes", "title": "Anodizing", "desc": "Anodizing grows a controlled oxide film on aluminum (and titanium, magnesium) by making the part the anode in an acid electrolyte - the reverse of plating, building oxide instead of depositing metal. Sulfuric-acid anodizing (Type II) gives 10-25 micron porous films that absorb dyes for colored architectural finishes; hard anodizing (Type III) grows 25-100+ microns of wear-resistant oxide for pistons and cookware.\nThe porous structure is the feature: dye or sealant fills the pores, then hot-water or nickel-acetate sealing closes them for corrosion resistance. Film thickness scales with charge (about 0.3 microns per A-min/dm2 for standard anodizing). Chromic-acid anodizing (Type I) gives thin films for aerospace bonding. Titanium anodizing produces interference colors for medical and jewelry use without dyes.", "how": "Anodizers rack aluminum parts, etch and desmut, then anodize at controlled current density and temperature - cold baths for hard coat. They dye in the porous state if color is wanted, then seal to lock in corrosion resistance. Thickness is verified by eddy-current gauges; sealing quality by the dye-stain test. Process control centers on bath concentration, temperature, and ampere-minutes - the anodizing analogue of Faraday timing.", "keys": ["Part is the anode; oxide grows instead of metal depositing.", "Type II (sulfuric): decorative, dyeable. Type III (hard): wear-resistant.", "Porous film absorbs dye, then sealing closes pores.", "Thickness scales with charge: ~0.3 um per A-min/dm2.", "Titanium anodizing colors by interference, no dye needed."], "reqs": ["Correct aluminum alloy (5xxx/6xxx anodize well; high-silicon casts poorly).", "Clean, etched, desmutted surface.", "Bath temperature and current density control."], "stds": ["Anodic coatings per MIL-A-8625 / ASTM B580.", "Sealing quality per ASTM B680 dye-stain test."], "cites": ["Wernick S, Pinner R, Sheasby PG. The Surface Treatment and Finishing of Aluminium. 5th ed. ASM; 1987.", "Schlesinger M, Paunovic M. Modern Electroplating. 5th ed. Wiley; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Anodizing time for target oxide thickness.\"\"\"\nrate = 0.3  # um per A-min per dm2\ntarget_um, area_dm2, I_A = 20.0, 4.0, 12.0\ncharge_needed = target_um / rate * area_dm2  # A-min\nt_min = charge_needed / I_A\nprint(f\"For {target_um} um on {area_dm2} dm2 at {I_A} A: {t_min:.0f} min\")\n"}, {"tier": "Compounded", "g": "Industrial Processes", "title": "Chlor-Alkali Process", "desc": "The chlor-alkali process electrolyzes brine into chlorine, hydrogen, and sodium hydroxide - three of industry's highest-volume chemicals. Modern membrane cells separate anode and cathode compartments with a cation-exchange membrane, replacing mercury and diaphragm cells for environmental and efficiency reasons.\nChlorine goes to PVC, water treatment, and chemicals; caustic soda to paper, alumina, and soaps; hydrogen increasingly to fuel or on-site use. The process is enormously electricity-intensive - roughly half the cost is power - so cell voltage (overpotentials plus membrane resistance) is the economic battleground. Oxygen-depolarized cathodes, which reduce O2 instead of evolving H2, cut energy use substantially where hydrogen has no value.", "how": "Operators feed purified brine (calcium and magnesium removed to protect membranes), run at high current density with dimensionally stable anodes (RuO2/IrO2 on titanium), and manage caustic concentration against back-migration. Cell voltage is tracked relentlessly - millivolts times kiloamperes is real money. Membrane life, brine purity, and current efficiency are the KPIs. Chlorine handling follows strict safety practice: it is toxic and the process co-produces hydrogen, so gas separation integrity is safety-critical.", "keys": ["Brine electrolysis makes Cl2, H2, and NaOH - all high-volume chemicals.", "Membrane cells replaced mercury/diaphragm designs.", "Electricity is ~half the cost - cell voltage is the battleground.", "Brine purity protects membranes; Ca/Mg must be removed.", "Oxygen-depolarized cathodes cut energy where H2 has no value."], "reqs": ["Purified brine feed (ppb-level hardness).", "Dimensionally stable anodes and intact membranes.", "Safe Cl2/H2 gas handling systems."], "stds": ["Cell performance per industry membrane-cell benchmarks.", "Chlorine safety per the Chlorine Institute pamphlets."], "cites": ["O'Brien TF, Bommaraju TV, Hine F. Handbook of Chlor-Alkali Technology. Springer; 2005.", "Bockris JO, Reddy AKN. Modern Electrochemistry. 2nd ed. Plenum; 1998."], "demo": "#!/usr/bin/env python3\n\"\"\"Chlor-alkali: energy per tonne of chlorine.\"\"\"\nV_cell, eff = 3.1, 0.96  # V, current efficiency\nM_cl2, n, F = 70.9, 2, 96485.0\n# kWh per tonne Cl2 = V * nF/M / eff\nkwh_per_t = V_cell * n * F / (M_cl2 / 1000) / eff / 3.6e6\nprint(f\"Energy: {kwh_per_t:.0f} kWh per tonne Cl2\")\nprint(f\"At $0.06/kWh: ${kwh_per_t*0.06:.0f} electricity per tonne\")\n"}, {"tier": "Compounded", "g": "Industrial Processes", "title": "Aluminum Smelting: Hall-Heroult", "desc": "The Hall-Heroult process dissolves alumina in molten cryolite at ~960 C and electrolyzes it with carbon anodes, producing aluminum at the cathode and CO2 at the anode. Two reactions dominate the cost: electricity (about 13-15 MWh per tonne of aluminum) and anode carbon consumption.\nCells run at hundreds of kiloamperes in long potlines; magnetic fields stir the metal pad and must be managed for stability. The process is why aluminum is called solid electricity - smelters locate where power is cheap. Inert-anode research aims to eliminate CO2 by evolving oxygen instead, which would decarbonize the metal's production step.", "how": "Operators control alumina feed to hold dissolved concentration in the narrow efficient window, manage anode-cathode distance against voltage and stability, and tap metal on schedule. Cell voltage (~4 V) times huge current is the energy bill, so current efficiency (typically 93-96%) is guarded via thermal and magnetic modeling. Potline design balances busbar magnetics, alumina feeding, and fume capture (fluorides). Recycling aluminum uses ~5% of smelting energy, which is why scrap loops matter enormously.", "keys": ["Alumina dissolved in cryolite, electrolyzed with carbon anodes at ~960 C.", "~13-15 MWh per tonne - aluminum is solid electricity.", "Carbon anodes are consumed, evolving CO2.", "Current efficiency 93-96% guarded by thermal/magnetic control.", "Recycling uses ~5% of primary energy."], "reqs": ["Alumina feed control in the efficient concentration window.", "Stable anode-cathode distance and thermal balance.", "Cheap, reliable electricity supply."], "stds": ["Cell energy per IAI smelting benchmarks.", "Fluoride emissions per EPA/industry standards."], "cites": ["Grjotheim K, Kvande H, eds. Introduction to Aluminium Electrolysis. 2nd ed. Aluminium-Verlag; 1993.", "Bockris JO, Reddy AKN. Modern Electrochemistry. 2nd ed. Plenum; 1998."], "demo": "#!/usr/bin/env python3\n\"\"\"Hall-Heroult: energy and anode carbon per tonne Al.\"\"\"\nV, eff = 4.2, 0.94\nM_al, n, F = 27.0, 3, 96485.0\nkwh_t = V * n * F / (M_al / 1000) / eff / 3.6e6\nc_kg = 1000 / M_al * 12.0 / 0.9  # ~theoretical C + excess\nprint(f\"Energy: {kwh_t:.0f} kWh/tonne Al\")\nprint(f\"Anode carbon: ~{c_kg:.0f} kg/tonne Al\")\n"}, {"tier": "Compounded", "g": "Energy Devices", "title": "Fuel Cell Principles", "desc": "Fuel cells convert fuel and oxidant directly to electricity without combustion, sidestepping the Carnot limit: hydrogen and oxygen become water plus current, with theoretical efficiency from delta_G/delta_H (~83% for H2/O2 at 25 C). Types are named for their electrolyte - PEM, alkaline, phosphoric acid, molten carbonate, solid oxide - each with its temperature, fuel tolerance, and application.\nPEM fuel cells dominate vehicles and backup power: fast start, high power density, but platinum catalysts and CO-sensitive anodes. Solid-oxide cells run at 600-1000 C on natural gas or hydrogen for stationary power with fuel flexibility. Polarization curves show the same three losses as electrolyzers in reverse: activation, ohmic, concentration. Hydrogen infrastructure and cost remain the adoption gates.", "how": "Designers pick the cell type by application temperature and fuel, manage water ruthlessly in PEM cells (membrane must stay hydrated but electrodes unflooded), and stack cells in series for voltage. Platinum loading is minimized with alloy catalysts and nanostructuring. System design adds reformers or hydrogen storage, air compressors, and thermal management - the stack is half the system. Durability targets (5000+ hours vehicles, 40000+ stationary) drive materials choices.", "keys": ["Direct fuel-to-electricity conversion, no Carnot limit.", "H2/O2 theoretical efficiency ~83% at 25 C.", "PEM for vehicles; solid oxide for stationary power.", "Water management makes or breaks PEM cells.", "Same three losses as electrolyzers: activation, ohmic, concentration."], "reqs": ["Fuel and oxidant supply with required purity.", "Operating temperature matched to cell type.", "Water and thermal management design."], "stds": ["Fuel-cell testing per IEC 62282.", "Hydrogen fuel quality per ISO 14687."], "cites": ["Larminie J, Dicks A. Fuel Cell Systems Explained. 2nd ed. Wiley; 2003.", "O'Hayre R et al. Fuel Cell Fundamentals. 3rd ed. Wiley; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"PEM fuel cell: theoretical efficiency and stack voltage.\"\"\"\ndG, dH = -237.1, -285.8  # kJ/mol H2\neff_th = dG / dH\nE_rev = 237.1e3 / (2 * 96485)\ncells, V_op = 400, 0.70\nprint(f\"Theoretical efficiency: {eff_th*100:.1f}%\")\nprint(f\"Reversible voltage: {E_rev:.2f} V; {cells}-cell stack at {V_op} V: {cells*V_op:.0f} V\")\n"}, {"tier": "Compounded", "g": "Kinetics & Methods", "title": "Electrochemical Sensors", "desc": "Electrochemical sensors turn chemistry into electrical signals at the point of need. Potentiometric sensors (pH, ion-selective electrodes) read voltage at zero current. Amperometric sensors (glucose strips, dissolved-oxygen probes) read current at fixed potential, proportional to concentration via diffusion-limited current. Conductometric sensors read solution conductivity.\nThe glucose test strip - billions used yearly - is amperometric: glucose oxidase generates hydrogen peroxide, oxidized at the electrode for a current proportional to glucose. Clark oxygen electrodes hide the cathode behind a gas-permeable membrane for selectivity. Modern arrays multiplex dozens of analytes on one chip for blood-gas analyzers and environmental monitors.", "how": "Developers choose the transduction mode by analyte and matrix, engineer selectivity with membranes and enzymes, and calibrate against standards with drift correction. Microfabrication puts electrodes, references, and fluidics on disposable chips. Validation covers interference testing (ascorbic acid vs glucose is the classic), shelf life, and hematocrit or matrix effects. Regulatory clearance for medical sensors demands clinical accuracy trials, not just lab curves.", "keys": ["Potentiometric: voltage. Amperometric: current. Conductometric: conductivity.", "Glucose strips: enzyme generates peroxide, current reads glucose.", "Membranes engineer selectivity (Clark O2 electrode).", "Diffusion-limited current makes amperometric sensors quantitative.", "Interference testing and drift correction are mandatory."], "reqs": ["Selective recognition element (membrane, enzyme).", "Calibration standards spanning the range.", "Interference and matrix-effect validation."], "stds": ["Glucose meters per ISO 15197 accuracy requirements.", "Sensor validation per CLSI guidelines."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Janata J. Principles of Chemical Sensors. 2nd ed. Springer; 2009."], "demo": "#!/usr/bin/env python3\n\"\"\"Amperometric sensor calibration line.\"\"\"\n# i = S*C + b ; fit standards, read unknown\nstds = [(0.0, 0.02), (5.0, 1.02), (10.0, 2.01), (20.0, 4.03)]  # mM, uA\nn = len(stds)\nsx = sum(c for c, i in stds); sy = sum(i for c, i in stds)\nsxx = sum(c * c for c, i in stds); sxy = sum(c * i for c, i in stds)\nS = (n * sxy - sx * sy) / (n * sxx - sx * sx)\nb = (sy - S * sx) / n\ni_unk = 2.55\nprint(f\"Calibration: i = {S:.3f}*C + {b:.3f}\")\nprint(f\"Unknown at {i_unk} uA: {(i_unk-b)/S:.2f} mM\")\n"}, {"tier": "Advanced", "g": "Energy Devices", "title": "Lithium-Ion Battery Chemistry", "desc": "Lithium-ion cells shuttle Li+ between a graphite anode and a transition-metal-oxide cathode (LCO, NMC, NCA, LFP) through an organic electrolyte, with electrons forced around the external circuit - the rocking-chair mechanism. Cell voltage (~3.7 V nominal) is the difference between electrode potentials; capacity is set by how much lithium the electrodes reversibly host.\nThe solid-electrolyte interphase (SEI) - a passivation film formed on first charge - is what makes the chemistry viable, at the cost of initial lithium loss. Degradation modes (SEI growth, lithium plating, cathode cracking, electrolyte oxidation) accumulate with cycling, heat, and high voltage. NMC811 pushes nickel for energy density; LFP trades energy for life, safety, and cost. Battery management systems guard the voltage, temperature, and current windows that keep degradation slow.", "how": "Cell designers balance energy vs power with electrode thickness (thin for power, thick for energy), choose cathode chemistry by application, and engineer the SEI with electrolyte additives (fluoroethylene carbonate and friends). Formation cycling builds the SEI under controlled conditions. BMS algorithms estimate state of charge and health from voltage, current, temperature, and impedance. Thermal design keeps cells in the 15-35 C sweet spot; outside it, aging accelerates or plating begins.", "keys": ["Rocking-chair: Li+ shuttles between graphite and metal-oxide electrodes.", "SEI film makes the chemistry viable; costs first-cycle lithium.", "NMC for energy density; LFP for life, safety, cost.", "Degradation: SEI growth, plating, cathode cracking, electrolyte oxidation.", "BMS guards voltage, temperature, current windows."], "reqs": ["Electrode pair with matched reversible capacities (N/P ratio).", "Electrolyte stable at both electrode potentials.", "Formation protocol and BMS limits."], "stds": ["Cell testing per IEC 62660; safety per UL 1642 / IEC 62133.", "Capacity in Ah; energy in Wh with nominal voltage stated."], "cites": ["Tarascon JM, Armand M. Issues and challenges facing rechargeable lithium batteries. Nature 414:359-367; 2001.", "Goodenough JB, Kim Y. Challenges for rechargeable Li batteries. Chem Mater 22:587-603; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Li-ion: theoretical capacity of graphite and NMC811.\"\"\"\nF = 96485.0\n# graphite LiC6: 1 Li per 72.06 g ; NMC811 ~ 200 mAh/g practical\nq_graphite = F / 72.06 / 3.6  # mAh/g\nprint(f\"Graphite theoretical: {q_graphite:.0f} mAh/g\")\nprint(\"NMC811 practical: ~200 mAh/g; LFP practical: ~160 mAh/g\")\n# pack energy\ncells, Vnom, Ah = 96, 3.7, 150.0\nprint(f\"96s pack: {cells*Vnom*Ah/1000:.1f} kWh\")\n"}, {"tier": "Advanced", "g": "Energy Devices", "title": "Solid-State Battery Electrochemistry", "desc": "Solid-state batteries replace the flammable liquid electrolyte with a ceramic or sulfide solid electrolyte, promising higher energy density (lithium-metal anodes become viable) and intrinsic safety. The core challenge is the solid-solid interface: maintaining intimate ionic contact through cycling as electrodes breathe, without the liquid that forgivingly wets every surface.\nSulfide electrolytes reach liquid-like conductivities but release H2S with moisture; oxides (LLZO) are stable but stiff and hard to process; polymers are manufacturable but less conductive. Dendrites still penetrate solids along grain boundaries and defects. Stack pressure, interface coatings, and composite cathodes are the engineering levers. Commercialization hinges on manufacturing solid electrolyte films thin, large, and defect-free at cost.", "how": "Developers select electrolyte chemistry by the conductivity-stability-processability triangle, engineer cathode composites mixing active material, electrolyte, and carbon for percolation, and protect interfaces with nanoscale coatings (e.g., LiNbO3 on NMC). They apply stack pressure to maintain contact and test dendrite resistance with critical-current-density measurements. Dry-room processing is stricter than for liquid cells (sulfides demand it). Validation runs the full matrix: rate, temperature, pressure, and long cycling with impedance tracking.", "keys": ["Solid electrolyte enables lithium-metal anodes and removes flammable liquid.", "The solid-solid interface is the core challenge.", "Sulfides conduct well but hate moisture; oxides are stable but stiff.", "Dendrites penetrate along grain boundaries and defects.", "Stack pressure, coatings, and composite cathodes are the levers."], "reqs": ["Electrolyte with >1 mS/cm conductivity and wide stability window.", "Interface engineering for persistent contact.", "Moisture-free processing environment."], "stds": ["Ionic conductivity in mS/cm with temperature stated.", "Critical current density reported with stack pressure."], "cites": ["Janek J, Zeier WG. A solid future for battery development. Nature Energy 1:16141; 2016.", "Manthiram A, Yu X, Wang S. Lithium battery chemistries enabled by solid-state electrolytes. Nature Rev Mater 2:16103; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Solid electrolyte: required thickness for target ASR.\"\"\"\n# area-specific resistance ASR = thickness / conductivity\nasr_target = 10.0  # ohm-cm2\nfor sigma_ms, name in ((10, \"sulfide\"), (1, \"oxide\"), (0.1, \"polymer\")):\n    sigma = sigma_ms / 1000  # S/cm\n    t_um = asr_target * sigma * 1e4\n    print(f\"  {name:8s} ({sigma_ms} mS/cm): max thickness {t_um:.0f} um\")\n"}, {"tier": "Advanced", "g": "Industrial Processes", "title": "Hydrogen Electrolysis at Scale", "desc": "Water electrolysis splits water into hydrogen and oxygen with electricity - the green-hydrogen pathway when powered renewably. Alkaline electrolyzers are the mature workhorse (nickel electrodes, KOH electrolyte, decades of life); PEM electrolyzers answer faster and run at higher current density with expensive iridium/platinum catalysts; solid-oxide cells promise top efficiency at high temperature using waste heat.\nEfficiency is voltage efficiency against the 1.23 V reversible (1.48 V thermoneutral) baseline; real stacks run 1.7-2.0 V. Capital cost, electricity price, and capacity factor decide the levelized cost of hydrogen - electrolyzers want cheap, steady power, which fights with variable renewables. System design adds gas drying, compression, water purification, and safety systems for H2/O2 separation integrity.", "how": "Project developers size stacks from the hydrogen demand via Faraday's law, choose technology by duty (alkaline for steady baseload, PEM for dynamic renewables-following), and model economics around electricity cost - typically 60-70% of levelized cost. They specify water purity (ASTM Type II or better for PEM), design thermal management for the waste heat, and implement gas-crossover monitoring as the safety-critical measurement. Efficiency is quoted against higher heating value with conditions stated.", "keys": ["Green hydrogen: electrolysis powered by renewable electricity.", "Alkaline mature; PEM dynamic; solid-oxide efficient with heat.", "Real stacks run 1.7-2.0 V vs 1.23 V reversible.", "Electricity is ~2/3 of hydrogen cost - capacity factor matters.", "Gas-crossover monitoring is safety-critical."], "reqs": ["Water purity per stack technology.", "Electricity cost and capacity factor for economics.", "H2/O2 separation integrity and monitoring."], "stds": ["Efficiency vs HHV with conditions stated; ISO 19880 for H2 systems.", "Water quality per ASTM D1193."], "cites": ["Ursua A, Gandia LM, Sanchis P. Hydrogen production from water electrolysis. Proc IEEE 100:410-426; 2012.", "Schmidt O et al. Future cost and performance of water electrolysis. Int J Hydrogen Energy 42:30470-30492; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Electrolyzer: H2 production and efficiency.\"\"\"\nV_cell, I_kA = 1.85, 100.0  # 100 kA plant module\nmol_per_s = I_kA * 1000 / (2 * 96485)\nkg_per_h = mol_per_s * 2.016e-3 * 3600\neff = 1.48 / V_cell  # vs thermoneutral\npower_MW = V_cell * I_kA / 1000\nprint(f\"H2: {kg_per_h:.1f} kg/h at {power_MW:.1f} MW\")\nprint(f\"Voltage efficiency: {eff*100:.1f}%; {power_MW*1000/kg_per_h:.1f} kWh/kg\")\n"}, {"tier": "Advanced", "g": "Industrial Processes", "title": "CO2 Electroreduction", "desc": "Electrochemical CO2 reduction converts waste carbon dioxide into fuels and chemicals - CO, formate, ethylene, ethanol - using electricity, closing the carbon loop when powered renewably. Copper is the unique catalyst making multi-carbon products; silver and gold favor CO; tin and bismuth favor formate. Selectivity is reported as faradaic efficiency per product.\nThe competing hydrogen evolution reaction fights for every electron, so catalyst and electrolyte design suppress it. Gas-diffusion electrodes feed CO2 directly to the catalyst, beating the low aqueous solubility that limits classic cells and reaching industrial current densities (>200 mA/cm2). System efficiency multiplies faradaic, voltage, and (for full devices) separation efficiencies - the economic bar is high but the prize is carbon-negative chemicals.", "how": "Researchers screen catalysts by faradaic efficiency at benchmark current densities, engineer gas-diffusion electrodes with hydrophobic layers to manage the triple-phase boundary, and choose electrolytes (often concentrated KOH or ionic liquids) that stabilize key intermediates. They report full product distributions - hidden products invalidate claims - with calibrated analytics (GC, NMR). Techno-economic analysis sets the selectivity and overpotential targets a process must hit to beat fossil routes.", "keys": ["CO2 to CO, formate, ethylene, ethanol - copper makes C2+ uniquely.", "Faradaic efficiency per product measures selectivity.", "Hydrogen evolution is the eternal competitor.", "Gas-diffusion electrodes beat CO2 solubility limits.", "Full product accounting is mandatory - hidden products invalidate claims."], "reqs": ["CO2 feed purity and delivery to the catalyst.", "Calibrated product analytics (GC, NMR).", "Benchmark current density and stability duration."], "stds": ["Faradaic efficiency reported per product with error bars.", "Stability in hours at stated current density."], "cites": ["Nitinol RM et al. A review of catalysts for the electroreduction of carbon dioxide. Chem Rev 119:7617-7672; 2019.", "De Luna P et al. What would it take for renewably powered electrosynthesis to displace petrochemical processes? Science 364:eaav3506; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"CO2 electrolyzer: product rates from faradaic efficiencies.\"\"\"\nI = 1000.0  # A\nF = 96485.0\n# product: (faradaic eff, electrons, molar mass g/mol)\nproducts = {\"CO\": (0.60, 2, 28.0), \"ethylene\": (0.25, 12, 28.05), \"H2\": (0.15, 2, 2.016)}\nfor name, (fe, n, M) in products.items():\n    g_per_h = I * fe / (n * F) * M * 3600\n    print(f\"  {name:9s}: {g_per_h:7.1f} g/h\")\n"}, {"tier": "Advanced", "g": "Kinetics & Methods", "title": "Electrocatalysis and Catalyst Design", "desc": "Electrocatalysis accelerates electrode reactions without being consumed, and its design rules are increasingly quantitative. The Sabatier principle - bind intermediates neither too strongly nor too weakly - produces volcano plots with the peak at optimal binding energy; platinum sits near the top for hydrogen evolution, which is why replacing it is hard.\nModern design spans scales: single-atom catalysts maximize metal utilization, nanostructuring exposes facets and strains lattices to tune binding, and operando spectroscopy watches the active site under working conditions. For oxygen evolution, iridium oxides remain the acid-stable standard despite cost; for oxygen reduction in fuel cells, Pt-alloys (Pt3Ni and descendants) multiply activity. Computational screening (DFT-calculated binding energies) now proposes candidates before synthesis.", "how": "Catalyst developers benchmark activity as overpotential at 10 mA/cm2 (geometric) plus mass and specific activities, measure electrochemically active surface area for normalization, and test stability with cycling and holds. They iterate composition, particle size, and support interactions, validating mechanisms with Tafel slopes and isotope effects. Scale-up confronts ink formulation, coating uniformity, and MEA integration - a great rotating-disk catalyst can fail in a real electrode. Cost modeling per kilowatt keeps noble-metal thrifting honest.", "keys": ["Sabatier principle: bind intermediates not too strong, not too weak.", "Volcano plots rank catalysts by binding energy.", "Benchmark: overpotential at 10 mA/cm2 with proper normalization.", "Single atoms, nanostructuring, and operando methods drive modern design.", "RDE success does not guarantee MEA success."], "reqs": ["Benchmark current density and normalization (mass, ECSA).", "Stability protocol: cycles, holds, start-stop.", "Cost per kW for practical relevance."], "stds": ["Activity reported with iR correction and normalization stated.", "Durability per DOE accelerated stress tests."], "cites": ["Seh ZW et al. Combining theory and experiment in electrocatalysis. Science 355:eaad4998; 2017.", "Jiao Y, Zheng Y, Jaroniec M, Qiao SZ. Design of electrocatalysts for oxygen- and hydrogen-involving energy conversion. Chem Soc Rev 44:2060-2086; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Volcano sketch: activity vs binding energy (Sabatier).\"\"\"\nimport math\n# activity ~ exp(-|dG - dG_opt| / RT), arbitrary units\nRT = 8.314 * 298 / 1000  # kJ/mol\ndG_opt = 0.0\nprint(\" dG_H* (eV)   relative activity\")\nfor dG in (-0.4, -0.2, -0.1, 0.0, 0.1, 0.2, 0.4):\n    act = math.exp(-abs(dG * 96.485 - dG_opt) / RT)\n    print(f\"   {dG:+.1f}        {act:.3f}\")\n"}, {"tier": "Advanced", "g": "Energy Devices", "title": "Photoelectrochemistry", "desc": "Photoelectrochemistry uses semiconductor electrodes to convert light directly into chemical energy: photons generate electron-hole pairs, the junction separates them, and the charges drive redox reactions like water splitting. Fujishima and Honda's 1972 TiO2 water-splitting demonstration founded the field.\nThe semiconductor bandgap must straddle the redox potentials (1.23 V for water splitting plus overpotentials), which forces tradeoffs: wide bandgaps are stable but waste sunlight, narrow ones corrode. Tandem structures stack junctions for voltage; protective overlayers (TiO2 by ALD) shield unstable absorbers. Solar-to-hydrogen efficiency is the figure of merit, with lab records above 15% and durability the persistent gap to application.", "how": "Researchers select absorbers by bandgap and band-edge positions, deposit protective and catalytic overlayers, and measure photocurrent-voltage curves under calibrated solar simulation. Incident-photon-to-current efficiency (IPCE) spectra reveal which wavelengths work. They report solar-to-hydrogen efficiency with faradaic efficiency confirmed by gas measurement - photocurrent alone can lie via corrosion currents. Stable operation for hundreds of hours under illumination is the practical milestone.", "keys": ["Light generates charges in a semiconductor; the junction separates them.", "Bandgap must straddle the redox potentials plus overpotentials.", "Wide bandgap: stable but inefficient. Narrow: efficient but corrodes.", "Protective overlayers shield unstable absorbers.", "Solar-to-hydrogen efficiency with confirmed faradaic efficiency is the metric."], "reqs": ["Calibrated solar simulator (AM 1.5G).", "Gas quantification to confirm faradaic efficiency.", "Stability testing under illumination."], "stds": ["STH efficiency per standard PEC benchmarking protocols.", "IPCE spectra with calibrated light source."], "cites": ["Fujishima A, Honda K. Electrochemical photolysis of water at a semiconductor electrode. Nature 238:37-38; 1972.", "Walter MG et al. Solar water splitting cells. Chem Rev 110:6446-6473; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Solar-to-hydrogen efficiency from photocurrent.\"\"\"\nj_mA, FE = 12.0, 0.95  # mA/cm2, faradaic efficiency\nP_sun_mW = 100.0\nSTH = j_mA * 1.23 * FE / P_sun_mW\nprint(f\"Photocurrent {j_mA} mA/cm2 -> STH {STH*100:.1f}%\")\n# bandgap limit hint\nprint(\"(Single-junction practical max ~ 15-18% STH)\")\n"}, {"tier": "Advanced", "g": "Kinetics & Methods", "title": "Bioelectrochemistry", "desc": "Bioelectrochemistry studies electron transfer in and with biological systems: redox proteins, enzyme electrodes, microbial fuel cells, and bioelectronics. Protein-film voltammetry adsorbs enzymes on electrodes and reads their catalytic cycles directly as current - hydrogenases, nitrogenases, and photosystems interrogated one layer at a time.\nEnzymatic fuel cells power implants from glucose; microbial fuel cells let exoelectrogenic bacteria (Geobacter, Shewanella) dump respiratory electrons onto anodes, treating wastewater while generating power. Direct electron transfer needs the redox center wired to the electrode - orientation and distance decide - while mediated systems shuttle electrons via small redox molecules. Biocompatibility and long-term stability are the translation hurdles.", "how": "Researchers immobilize enzymes with orientation control (SAMs, covalent attachment), verify direct electron transfer by the catalytic wave's potential matching the enzyme's, and measure turnover rates from limiting currents. Microbial systems are characterized by polarization curves and coulombic efficiency (electrons captured vs substrate consumed). Implantable designs confront foreign-body response and enzyme lifetime - months, not years, currently. Sterile technique and controls for abiotic currents separate biology from artifact.", "keys": ["Redox proteins and enzymes exchange electrons with electrodes.", "Protein-film voltammetry reads enzyme catalysis as current.", "Microbial fuel cells treat wastewater while generating power.", "Direct transfer needs wiring; mediated uses shuttles.", "Biocompatibility and enzyme lifetime are the translation hurdles."], "reqs": ["Enzyme/microbe immobilization with retained activity.", "Abiotic controls to rule out non-biological currents.", "Sterile technique for microbial systems."], "stds": ["Enzyme electrode reporting per bioelectrochemistry conventions.", "MFC performance per standard polarization/coulombic-efficiency methods."], "cites": ["Armstrong FA, Wilson GS. Recent developments in faradaic bioelectrochemistry. Electrochim Acta 45:2623-2645; 2000.", "Logan BE. Microbial Fuel Cells. Wiley; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Enzymatic electrode: catalytic current vs substrate (Michaelis-Menten).\"\"\"\ni_max, Km = 100.0, 2.0  # uA, mM\nprint(\" [S] (mM)   i_cat (uA)\")\nfor S in (0.5, 1, 2, 5, 10, 20):\n    i = i_max * S / (Km + S)\n    print(f\"  {S:5.1f}      {i:6.1f}\")\n"}, {"tier": "Advanced", "g": "Energy Devices", "title": "Supercapacitors and Pseudocapacitance", "desc": "Supercapacitors store energy electrostatically in the double layer (EDLC) or via fast surface redox (pseudocapacitance), delivering power densities far above batteries with lower energy density. Activated carbons give thousands of m2/g; RuO2 and MnO2 add pseudocapacitive farads; MXenes push volumetric performance.\nThe Ragone plot places them between capacitors and batteries: seconds-to-minutes discharge, million-cycle life, and wide temperature tolerance. Buses recapture braking energy, cranes smooth peaks, and memory backup rides through outages on supercapacitors. Hybrid devices pair a capacitive electrode with a battery electrode (lithium-ion capacitors) to split the difference. Voltage balancing across series cells is the pack-level discipline.", "how": "Engineers size supercapacitors from energy (1/2*C*V^2) and power (V^2/4*ESR) requirements, derate voltage for life (life halves roughly every 0.1-0.2 V above rating at temperature), and design active or passive balancing for series strings. They test with constant-current charge/discharge per IEC 62391, reporting capacitance, ESR, and leakage. Thermal design matters at high ripple currents - ESR heating is the life limiter.", "keys": ["EDLC: double-layer storage. Pseudocapacitance: fast surface redox.", "Power density far above batteries; energy density below.", "Million-cycle life and wide temperature range.", "Voltage derating buys life; balancing protects series strings.", "Lithium-ion capacitors hybridize toward batteries."], "reqs": ["Energy and power requirements for sizing.", "Operating voltage window and temperature.", "Balancing strategy for series strings."], "stds": ["Testing per IEC 62391.", "Capacitance in farads; ESR in milliohms."], "cites": ["Conway BE. Electrochemical Supercapacitors. Kluwer; 1999.", "Simon P, Gogotsi Y. Materials for electrochemical capacitors. Nature Mater 7:845-854; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Supercapacitor: energy, power, discharge time.\"\"\"\nC, V, ESR = 3000.0, 2.7, 0.3e-3  # F, V, ohm\nE_Wh = 0.5 * C * V ** 2 / 3600\nP_max = V ** 2 / (4 * ESR)\nprint(f\"Energy: {E_Wh:.2f} Wh; max power: {P_max/1000:.1f} kW\")\nprint(f\"Discharge at 100 A: {C*V/100:.0f} s\")\n"}, {"tier": "Advanced", "g": "Industrial Processes", "title": "Electrochemical Machining", "desc": "Electrochemical machining (ECM) dissolves metal anodically through a shaped cathode tool with a tiny gap, cutting hard alloys without tool wear, heat-affected zones, or residual stress - the inverse of electroplating used as a milling process. Turbine blades, gun barrels, and medical implants are ECM products.\nMaterial removal follows Faraday's law; the gap (0.1-0.5 mm) is held by tool feed matching dissolution rate, with high-velocity electrolyte flushing products and heat. Precision ECM reaches micron tolerances with pulsed current and careful flow design. Electrochemical grinding and deburring are gentler siblings. The process trades consumable tooling for electrolyte management and hydrogen handling.", "how": "Process engineers design the tool as the inverse of the desired shape corrected for the gap, set feed rate from Faraday's law at the operating current density, and engineer electrolyte flow to avoid stagnation (which causes stray attack). They monitor gap voltage as the control signal and filter electrolyte continuously. Safety practice handles hydrogen evolution and caustic or acidic electrolytes. Pulsed ECM tightens localization for fine features.", "keys": ["Anodic dissolution through a shaped cathode - plating in reverse.", "No tool wear, no heat-affected zone, no residual stress.", "Removal follows Faraday law; feed matches dissolution.", "Gap 0.1-0.5 mm held by voltage-controlled feed.", "Electrolyte flow design prevents stray attack."], "reqs": ["Tool shaped as the inverse of the target with gap allowance.", "Electrolyte flow and filtration system.", "Hydrogen ventilation and handling."], "stds": ["Dimensional tolerances per customer drawing; surface finish in Ra.", "ECM safety per standard electrochemical processing practice."], "cites": ["McGeough JA. Principles of Electrochemical Machining. Chapman and Hall; 1974.", "Rajurkar KP, Zhu D, McGeough JA, Kozak J, De Silva A. New developments in electro-chemical machining. CIRP Ann 48:567-579; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"ECM: feed rate from Faraday law (steel).\"\"\"\nM, n, rho, F = 55.85, 2, 7.87, 96485.0\ni_Acm2, eff = 50.0, 0.95  # A/cm2\n# volumetric removal rate cm3/s per cm2 = linear feed cm/s\nfeed = i_Acm2 * eff * M / (n * F * rho)  # cm/s\nprint(f\"Feed rate: {feed*60:.2f} mm/min\")\n"}, {"tier": "Advanced", "g": "Corrosion", "title": "Pourbaix Diagrams in Practice", "desc": "Pourbaix (potential-pH) diagrams map the thermodynamically stable phases of a metal-water system: immunity where the metal is stable, corrosion where ions are stable, passivity where oxides are stable. Lines for water reduction and oxidation bound the diagram; every corrosion engineer reads these maps.\nThe diagrams are thermodynamic, not kinetic - they say what can happen, not how fast. Real systems add chloride, which shrinks passive regions, and temperature shifts every boundary. Practitioners overlay operating points (measured potential and pH) to see which region the system lives in, then choose strategies: shift potential into immunity (cathodic protection), shift pH into passivity (inhibitors), or accept corrosion with allowance.", "how": "Engineers plot the measured corrosion potential and local pH on the diagram to diagnose the regime, then move the point deliberately: cathodic protection pushes potential down into immunity, alkaline inhibitors push pH into passivity. They remember the limits - kinetics may protect where thermodynamics predicts attack (titanium's passive film) or attack where immunity is predicted (complexing agents). Software (e.g., thermochemical packages) generates diagrams for alloy systems and elevated temperatures beyond textbook iron and copper.", "keys": ["Maps of immunity, corrosion, passivity vs potential and pH.", "Water stability lines bound every diagram.", "Thermodynamic: what can happen, not how fast.", "Chloride shrinks passive regions; temperature shifts boundaries.", "Move the operating point: potential into immunity, pH into passivity."], "reqs": ["System potential and pH measurements.", "Diagram for the actual alloy and temperature.", "Awareness of kinetic overrides."], "stds": ["Diagram construction per thermochemical data (e.g., NBS tables).", "Potential/pH measurement per standard practice."], "cites": ["Pourbaix M. Atlas of Electrochemical Equilibria in Aqueous Solutions. NACE; 1974.", "Revie RW, Uhlig HH. Corrosion and Corrosion Control. 4th ed. Wiley; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Iron Pourbaix: immunity/corrosion boundary at pH 7.\"\"\"\n# Fe2+ + 2e -> Fe, E0=-0.44; boundary E = E0 + 0.0295*log[Fe2+]\nE0 = -0.44\nprint(\" [Fe2+] (M)   E_boundary (V vs SHE)\")\nfor c in (1e-2, 1e-4, 1e-6):\n    import math\n    E = E0 + 0.0295 * math.log10(c)\n    print(f\"  {c:.0e}        {E:+.3f}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ELCHS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ELCHS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-electrochemistry-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('electrochemistry',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
